 dict(slug="stop-wasting-google-ads-money",
  title="How to stop wasting money on Google Ads",
  desc="A 15-minute check of your Google Ads search terms that shows where money goes on clicks that will never become customers, and how to block them.",
  h1="How to stop wasting money on Google Ads",
  lede="Most small accounts pay for some searches that will never turn into a customer. Here is how to find them in 15 minutes, without any special tools.",
  sections=[
   ("Why it happens", ["Google Ads matches your ads to what people type, and the match is looser than most owners expect. A plumber can end up paying for someone searching for plumbing jobs, a free DIY guide or a shop in another town. Each click costs the same, whether or not that person will ever call you."], []),
   ("The 15-minute check", ["You need only your own Google Ads account."],
    ["Open Google Ads and go to Insights and reports, then Search terms.",
     "Set the date range to the last 30 days and sort by cost, highest first.",
     "Read the top 30 rows. For each one ask: would this person buy from me? Mark every row that is clearly a no (jobs, free, DIY, training, a place you don't serve, a different service).",
     "Select the marked rows and add them as negative keywords, at campaign level. Use phrase match for a phrase like 'jobs', and exact match when only that exact search is the problem.",
     "Add the total cost of the marked rows to a note. That is roughly what the check saved over a month."]),
   ("Keep it from coming back", ["Repeat the check every month, because new searches appear all the time. Also look at location settings: choose 'people in or regularly in' your area, not 'people interested in' it, so you stop paying for clicks from outside your service area.", "Check the same account for call and form tracking. Without it, you cannot tell which searches ever produced an enquiry."], []),
  ],
  faq=[("How much can this save?","It depends on the account. A check of your own search terms shows the real figure, so there is no honest number to quote in advance."),
       ("Will blocking searches reduce my enquiries?","If you only block searches that clearly cannot become customers, it should not. Review a few of the blocked terms again after a month to make sure none were wrongly blocked.")]),

